    void UpdateAlternateShortcut() {
        if (!settings_.alternateShortcut) { ReleaseAlternateShortcut(); return; }
        if (!hwnd_ || alternateHotkeyRegistered_) return;
        if (RegisterHotKey(hwnd_.get(),kAlternateHotkeyId,MOD_CONTROL|MOD_SHIFT|MOD_NOREPEAT,VK_F12))
            alternateHotkeyRegistered_=true;
        else Wh_Log(L"[Shortcut] Ctrl+Shift+F12 unavailable (error %u)",GetLastError());
    }
